
  // генерируем магнитные катушки по кольцу ускорителя программно
  (function buildCoils(){
    const g = document.getElementById('coils');
    if(!g) return;
    const cx = 450, cy = 270, r = 170;
    for(let i=0;i<16;i++){
      const a = (i/16) * Math.PI * 2;
      const x = cx + Math.cos(a)*r, y = cy + Math.sin(a)*r;
      const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
      rect.setAttribute('x', x-9); rect.setAttribute('y', y-5);
      rect.setAttribute('width', 18); rect.setAttribute('height', 10);
      rect.setAttribute('transform', `rotate(${a*180/Math.PI+90} ${x} ${y})`);
      g.appendChild(rect);
    }
  })();

