    const [year, month, day] = input.split('-').map(Number);
    const dateObj = new Date(Date.UTC(year, month - 1, day));
    const dayName = DOW_NAMES[dateObj.getUTCDay()];
    const formatted = `${day} ${DOW_MONTHS[month - 1]} ${year} года`;
    resultEl.innerHTML = `${formatted}<br><span style="font-size:20px;font-weight:700;">${dayName}</span>`;
