  // ===== Универсальное хранилище: window.storage внутри Claude, localStorage — при локальном открытии файла =====
  const hasClaudeStorage = typeof window.storage !== 'undefined' && window.storage !== null;
  async function storageGet(key){
    if(hasClaudeStorage){
      try{ return await window.storage.get(key); } catch(e){ return null; }
    }
    try{
      const v = localStorage.getItem(key);
      return v !== null ? {key, value: v, shared: false} : null;
    } catch(e){ return null; }
  }
  async function storageSet(key, value){
    if(hasClaudeStorage){
      try{ return await window.storage.set(key, value); } catch(e){ return null; }
    }
    try{ localStorage.setItem(key, value); return {key, value, shared:false}; } catch(e){ return null; }
  }
  async function storageDelete(key){
    if(hasClaudeStorage){
      try{ return await window.storage.delete(key); } catch(e){ return null; }
    }
    try{ localStorage.removeItem(key); return {key, deleted:true, shared:false}; } catch(e){ return null; }
  }

