  applyVisitVariety();
  updateStreak();
  initArchiveCounter();
  loadStats().then(checkAchievements);
  checkSharedQuizResult();

  function showSeasonChronicle(){
    const lines = SEASON_CHRONICLE.map(e => {
      const parts = [`СЕЗОН ${e.s} — ${e.title}`, e.text];
      if(e.reveal) parts.push(e.reveal);
      parts.push(e.finale);
      return parts.join('\n');
    });
    return "ХРОНИКА ВРЕМЕННОЙ ЛИНИИ (архив CW):\n\n" + lines.join('\n\n');
  }

